# owner: platform
"""Lay students out in rows of seats for printing."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

# ---
def seat_rows(
    students: Iterable[Student], per_row: int
) -> List[str]:
    """One line of text per row, sorted by last name."""
    roster = list(students)
    check_seating(roster, per_row)
    ordered = sorted(roster, key=last_name_order)
    return format_rows(split_rows(ordered, per_row))

# ---
def check_seating(
    students: List[Student], per_row: int
) -> None:
    """Reject a bad seat count or an empty roster."""
    if per_row <= 0:
        raise ValueError(f"bad seat count: {per_row}")
    if not students:
        raise ValueError("no students to seat")

# ---
def last_name_order(student: Student) -> Tuple[str, str]:
    """Sort key: last name, then first name for ties."""
    return (student.last_name, student.first_name)

# ---
def split_rows(
    ordered: List[Student], per_row: int
) -> List[List[Student]]:
    """Consecutive slices of the roster, one per row."""
    return [
        ordered[start:start + per_row]
        for start in range(0, len(ordered), per_row)
    ]

# ---
def format_rows(rows: List[List[Student]]) -> List[str]:
    """Number the rows from one and label each one."""
    return [
        format_row(number, seated)
        for number, seated in enumerate(rows, 1)
    ]

# ---
def format_row(number: int, seated: List[Student]) -> str:
    """Label one row and list its students."""
    names = [item.display_name for item in seated]
    return f"Row {number}: {' | '.join(names)}"
